(function(root){'use strict';
const nodes={PROLOGO:['radio'],N1_COCINA:['resources'],N1_MINIMERCADO_POST:['interrogation','firstAid'],N1_OFICINA_EXPLORAR:['investigation'],N2A_EMBOSCADA_INTRO:['chase']};
const config={
radio:{title:'Radio policial',prompt:'Hay dos avisos en la frecuencia. Decide dónde enviar apoyo.',options:[['Enviar una patrulla al minimercado',{dispatch:true},'Una unidad queda disponible para respaldar la investigación.'],['Mantener la patrulla junto a Mateo',{dispatch:false},'Mateo conserva el apoyo cercano. El canal queda abierto.']]},
resources:{title:'Recursos de la familia',prompt:'El presupuesto no alcanza para todo. Elige cómo repartirlo.',options:[['Comprar el inhalador · $70',{money:-70,medicine:1},'Sofía tiene una dosis de respaldo.'],['Reservar $50 para el informante',{money:-50,evidence:1},'Obtienes una pista sobre las transferencias.'],['Dividir el presupuesto · $80',{money:-80,medicine:1,evidence:1},'Aseguras medicina y una pista.']]},
interrogation:{title:'Interrogatorio',prompt:'Uno de los detenidos está dispuesto a hablar. Escoge tu enfoque.',options:[['Presentar las pruebas y pedir cooperación',{trust:2,evidence:1},'Confirma que Vargas recibe pagos de Marcos.'],['Ofrecer protección a su familia',{trust:1,dispatch:true},'Acepta colaborar si proteges a su familia.'],['Presionarlo con una acusación formal',{trust:-1},'Se cierra y solo confirma el nombre del almacén.']]},
investigation:{title:'Tablero de investigación',prompt:'Conecta dos pistas para respaldar la acusación contra Vargas.',options:[['Transferencias bancarias + firma de Vargas',{evidence:2},'Coinciden fechas, cuentas y firma: una prueba sólida.'],['Factura médica + dibujo de Sofía',{trust:1},'Explica el motivo de Mateo, pero no prueba el soborno.'],['Placas del camión + caja de herramientas',{evidence:1},'La conexión señala la ruta de contrabando.']]},
chase:{title:'Persecución en el puente',prompt:'Dos motos cierran el paso. Elige una maniobra antes del enfrentamiento.',options:[['Frenar y tomar la curva interior',{evidence:1,dispatch:true},'Evitas la emboscada y recuperas el teléfono del mensajero.'],['Acelerar por el carril mojado',{dispatch:false},'Ganas distancia, pero el teléfono cae en la calzada.'],['Cerrar el paso junto al retén',{evidence:1,witnessSafe:true},'Una moto se detiene y su conductor queda bajo custodia.']]},
firstAid:{title:'Primeros auxilios',prompt:'Mateo y un testigo necesitan atención. Decide a quién destinar los suministros de asistencia del juego.',options:[['Atender al testigo',{medicine:-1,witnessSafe:true,trust:1},'El testigo se recupera y acepta declarar.'],['Atender a Mateo',{medicine:-1,health:20},'Mateo recupera fuerzas.'],['Reservar los suministros para Sofía',{},'Conservas los suministros que te quedan para la familia.']]}
};
function initial(){return{evidence:0,trust:0,money:100,medicine:1,dispatch:false,witnessSafe:false,used:[],results:{}}}
function allowed(a,type,index){const option=config[type]?.options[index];if(!option)return false;return a.money+(option[1].money||0)>=0&&a.medicine+(option[1].medicine||0)>=0}
function resolve(a,node,type,index){const key=node+':'+type;if(!(nodes[node]||[]).includes(type)||a.used.includes(key)||!allowed(a,type,index))return null;const [,delta,text]=config[type].options[index];for(const [k,v]of Object.entries(delta)){if(k==='health')continue;a[k]=typeof v==='boolean'?v:a[k]+v}a.used.push(key);a.results[key]=text;return{text,health:delta.health||0}}
function summary(a){return `Pruebas: ${a.evidence} · Confianza: ${a.trust}\nFondos: $${a.money} · Suministros: ${a.medicine}\nApoyo: ${a.dispatch?'disponible':'sin unidad de respaldo'}\nTestigo: ${a.witnessSafe?'a salvo':'sin protección confirmada'}`}
const api={nodes,config,initial,allowed,resolve,summary};if(typeof module!=='undefined')module.exports=api;else root.GameActivities=api;
})(typeof window!=='undefined'?window:globalThis);
